() => {
  // Try to find and close the survey overlay
  const overlays = document.querySelectorAll('[aria-label*="close" i], [aria-label*="dismiss" i], button[type="button"]');
  for (const overlay of overlays) {
    const text = overlay.textContent || '';
    if (text.includes('Skip') || text.includes('Close') || overlay.getAttribute('aria-label')?.includes('close')) {
      overlay.click();
      return 'closed: ' + (overlay.getAttribute('aria-label') || overlay.textContent);
    }
  }
  // Look for any skip button
  const buttons = document.querySelectorAll('button');
  for (const btn of buttons) {
    if (btn.textContent.includes('Skip') || btn.textContent.includes('Maybe later')) {
      btn.click();
      return 'clicked: ' + btn.textContent;
    }
  }
  return 'no skip button found';
}()
